function me = loadMotionEnergy(obj,meta,params,datapth,varargin)

if nargin > 4
    returnAfterLoad = varargin{1};
else
    returnAfterLoad = 0;
end

% %------------------------------------------------------------
% % --first check to see if obj has an 'me' and has thresh--
